import {store,pocket,url,asset,params,evidenceArticle,commandForm,mountPage,recordTable,tableCSV,downloadLocal,esc,canRead,truth} from '../arg-ui.js?v=43';
import {EVIDENCE,MATERIALS} from '../arg-content.js?v=43';
import {truthy} from '../arg-engine.js?v=43';
import {CARD_ROWS} from '../network-content.js?v=43';
const app=document.querySelector('#app');let range={from:'2025-03-12',to:'2025-03-14'},queried=truthy(store.get(),'actions','cardQueried'),archiveQuery='',includeArchived=false;
const nav=[['home','服务首页'],['card','一卡通消费明细'],['timeline','到场记录核查'],['menu','每周菜谱与采购公示'],['outage','餐具维保与维修归档'],['contract','采购验收协议'],['summary','健康投诉归档公示']];
function frame(view,body){app.innerHTML=`<section class="portal-site"><div class="portal-utility">青禾高级中学后勤服务中心 · 信息公开存档</div><header class="portal-masthead"><span class="portal-brand"><b>禾</b><span>智慧后勤服务大厅<small>QINGHE CAMPUS SERVICES</small></span></span></header><div class="portal-notice"><b>通知</b><span>历史工单请一并检索归档。工作卡记录需结合原始签收核查。</span></div><div class="portal-layout"><aside class="portal-sidebar">${nav.map(([id,text])=>`<a href="index.html?view=${id}" ${id===view?'aria-current="page"':''}>${text}</a>`).join('')}</aside><div class="portal-main">${body}</div></div><footer class="portal-footer">青禾高级中学后勤服务中心 · 2018校内服务平台</footer></section>`;}
const heading=(a,b='')=>`<header class="network-page-title"><h1>${a}</h1><p>${b}</p></header>`;
function card(){let body=heading('学生一卡通消费查询','查询仅包含持卡人授权的交易范围。')+`<details class="portal-local-note"><summary>杰哥交给by的查询便笺</summary><p>学号20220327，授权口令与jiege资料柜相同。</p>${MATERIALS.caseDocs.pickup.body.replace(/href="#[^"]+"/g,`href="${url('pan',{folder:'jie'})}"`)}</details>`;
 if(!truthy(store.get(),'accounts','card')){frame('card',body+`<form id="cardLogin" class="portal-form"><label>学号<input name="student" required inputmode="numeric" autocomplete="off"></label><label>授权查询口令<input name="password" type="password" required></label><button class="portal-button">登录查询</button><p data-response></p></form>`);commandForm(app.querySelector('form'),'login',d=>({account:'card',student:d.get('student'),password:d.get('password')}));return;}
 const rows=CARD_ROWS.filter(r=>r[1].slice(0,10)>=range.from&&r[1].slice(0,10)<=range.to);body+=`<form id="queryCard" class="portal-query"><label>开始日期<input type="date" name="from" value="${range.from}" required></label><label>结束日期<input type="date" name="to" value="${range.to}" required></label><button class="portal-button">查询</button></form>`;
 if(queried)body+=recordTable({title:'学生20220327消费明细',columns:['流水','时间','窗口 / 机号','摘要','金额','凭条'],rows},{key:'card',interactive:true})+(rows.some(r=>r[0]==='C0313-2147')?`<section class="portal-receipt" data-evidence="receipt"><div><small>2025-03-13 21:47:12 / QH-C02</small><h2>￥18.00</h2><p>火鸡面12元、饭团4元、紫菜汤2元，取餐号0367。</p><p>商品项只能说明买过什么。<a href="${url('pan',{folder:'jie'})}">和杰哥给的桌面照片对照</a>，才能核对谁吃了哪份。</p></div><img src="${asset('assets/meal-receipt.svg')}" alt="0313-0367取餐凭条留存"></section>`:'<p>这段范围没有目标凭条，可以修改日期。</p>');frame('card',body);app.querySelector('#queryCard').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);range={from:d.get('from'),to:d.get('to')};queried=true;const r=store.dispatch('card',range);pocket.feedback(r.message);if(r.ok){card();import('../arg-ui.js?v=43').then(m=>m.watchReads());}});}
function timeline(){if(!canRead(store.get(),'swipe'))return frame('timeline',heading('核查阅览需授权','后勤流水未包含在普通学生查询内。')+`<p><a href="${url('pan',{folder:'clinic'})}">从小范提供的核查目录进入</a>，请保留原件编号。</p>`);
 const ids=['roster','swipe','attendance','signoff'];frame('timeline',heading('到场记录核查工作台','四份来源可以分别标记和下载。单张卡不能证明使用者。')+`${truthy(store.get(),'actions','timelineChecked')?'<p class="arg-verified">✓ 这组时间线质疑已核对。</p>':''}<form id="timelineForm">${ids.map(id=>`<section class="portal-record-block"><div data-evidence="${id}">${recordTable(EVIDENCE[id],{choice:id,key:id,selected:store.get().marks[id]?.value||[]})}</div><button type="button" data-export-evidence="${id}">下载整份CSV</button></section>`).join('')}<label>这些记录支持什么？<select name="explanation" required><option value="">请选择</option><option value="infection">已经证明某人导致感染</option><option value="borrow">公用卡可以借，所以无须再查</option><option value="proxy">本人到过食堂，“全程在场”为事后代填</option></select></label><button class="portal-button">提出这组时间线质疑</button><p data-response></p></form><p>关联资料：<a href="${url('pan',{folder:'clinic',file:'draft'})}">小范草稿</a>　<a href="${url('pan',{folder:'clinic',file:'medical'})}">复查送达记录</a></p>`);commandForm(app.querySelector('#timelineForm'),'timeline');}
function outage(){let body=heading('餐具设备维修报备','办结工单进入历史归档，不在当前处理中展开。')+`<form id="workorders" class="portal-query"><label>设备 / 工单号<input name="q" value="${esc(archiveQuery)}" placeholder="设备、回路或维修编号" maxlength="80"></label><label class="portal-check"><input type="checkbox" name="archive" ${includeArchived?'checked':''}>含归档</label><button class="portal-button">检索</button></form><p>在办：WX0403-02水房水龙头漏水；WX0403-06二楼灯管更换。</p>`;if(includeArchived&&/消毒|消杀|餐具|回路|wx0313|xd-02/i.test(archiveQuery))body+=evidenceArticle('outage',{compact:true})+`<p>相关附件由核查人员留存：<a href="${url('pan',{folder:'audit'})}">L-0313加密导出包</a>。同一设备在断电时能否持续通电高温，需对原台账。</p>`;else if(archiveQuery)body+='<p>没有命中对应工单。历史报备请一并查归档。</p>';frame('outage',body);app.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);archiveQuery=String(d.get('q'));includeArchived=d.has('archive');outage();import('../arg-ui.js?v=43').then(m=>m.watchReads());});}
mountPage(()=>{const view=params().get('view')||'home';if(view==='card')card();else if(view==='timeline')timeline();else if(view==='outage')outage();else if(['contract','summary','roster','swipe','attendance','signoff'].includes(view))frame(view,evidenceArticle(view));else if(view==='menu')frame(view,heading('每周菜谱与采购公示')+'<p>周四夜宵：火鸡面12元、饭团4元、紫菜汤2元；车仔面由另一窗口供应。餐具消杀按单独服务合同验收。</p>'+`<p><a href="index.html?view=contract">采购验收协议</a>　<a href="index.html?view=outage">设备维修公示</a></p>`);else frame('home',`<div class="portal-banner"><h1>后勤服务，一站办理</h1><p>消费记录 · 菜谱公示 · 设备报备</p></div><p>消费凭条请按自然日查询；后勤核查材料按授权范围开放。</p><p><a href="index.html?view=card">学生消费查询</a>　<a href="index.html?view=outage">维修归档检索</a></p><p>来源论坛：<a href="${url('forum',{thread:'reports'})}">关于就医经历的讨论</a>。涉及医疗复查，请从本人提供的资料核实。</p>`);});
